"""Write the baseline review pack: docs/baseline/SDEM-METAMODEL-0.8-review-pack.md.

A point-in-time snapshot for an independent reviewer (not regenerated by CI): what is being baselined, the evidence,
the known limitations, the review checklist and the sign-off. All counts are computed from the records when run.
Usage: python scripts/baseline_pack.py
"""
import glob, json, subprocess, sys
from collections import Counter
from datetime import date
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
from sdem.conformance import check_level, estate_index  # noqa: E402
from sdem.metamodel import Metamodel  # noqa: E402
from sdem.validate import check_schema  # noqa: E402

BASELINE = 'SDEM-METAMODEL-0.8'
OUT = ROOT / 'docs' / 'baseline' / f'{BASELINE}-review-pack.md'


def J(p): return json.loads((ROOT / p).read_text(encoding='utf-8'))


def hml(xs, key='confidence'):
    c = Counter(x.get(key) for x in xs); return c['high'], c['medium'], c['low']


def tests():
    r = subprocess.run([sys.executable, '-m', 'unittest', 'discover', '-s', 'tests'], cwd=ROOT, capture_output=True, text=True)
    ran = next((l for l in r.stderr.splitlines() if l.startswith('Ran ')), 'Ran ? tests'); return ran.split()[1], r.stderr.strip().splitlines()[-1]


def conformance(mm):
    err = warn = inst = 0; schemas = {json.loads(Path(p).read_text())['title']: json.loads(Path(p).read_text()) for p in glob.glob(str(ROOT / 'schema/entities/*/*.schema.json'))}; bad = 0
    for est in sorted(glob.glob(str(ROOT / 'examples' / '*') + '/')):
        docs = [json.loads(Path(f).read_text()) for f in sorted(glob.glob(est + 'a[1-4]-*.json'))]; idx = estate_index(docs)
        for d in docs:
            e, w, _ = check_level(d, mm, idx); err += len(e); warn += len(w); inst += len(d['instances'])
            bad += sum(1 for i in d['instances'] if check_schema(i, schemas[i['type']]))
    return len(glob.glob(str(ROOT / 'examples' / '*') + '/')), inst, err, warn, len(schemas), bad


def main():
    mm = Metamodel.load()
    ents = [e for f in sorted(glob.glob(str(ROOT / 'metamodel/a[1-4]-*.json'))) for e in json.loads(Path(f).read_text())['entities']]
    lr = J('metamodel/level-relationships.json'); rows = lr['constraints']
    types = J('schema/relationship-types.json')['relationships']; rules = J('metamodel/relationship-rules.json')['mappings']
    at = J('metamodel/entity-attributes.json'); attrs = [a for a in at['attributes'] if a['status'] == 'active']; common = at['common_attributes']; derived = at.get('derived_attributes', [])
    dep = [a for a in at['attributes'] if a['status'] == 'deprecated']
    ntests, tline = tests(); est, inst, err, warn, nschema, schema_bad = conformance(mm)
    ver = Counter(c['verification'] for c in rows)
    low_rows = [c for c in rows if c['confidence'] == 'low']
    lows = [f"`{a['entity']}.{a['name']}`" for a in attrs if a['confidence'] == 'low']
    gated = [e['type'] for e in ents if e.get('definition_source') == 'togaf_informed'] + [c['id'] for c in rows if c['verification'] == 'unverified_togaf']
    items = ents + rows + types + attrs + common + at['core_fields']
    H, M, L = hml(items); N = H + M + L
    o = [f'# {BASELINE} — Baseline Review Pack', '',
         f'> Prepared {date.today().isoformat()} by `python scripts/baseline_pack.py` from the records at commit `{subprocess.run(["git", "rev-parse", "--short", "HEAD"], cwd=ROOT, capture_output=True, text=True).stdout.strip()}`. A snapshot for review, not a living document.', '',
         '## 1. What a baseline is, and what you are asked to approve', '',
         f'A **baseline** freezes one reviewed version of the SDEM blueprint under a name, **{BASELINE}**. Tool adapters build against it, approved relationship records point to it, and later changes are made as new versions with a change log. Approving it means: *the model is fit to receive real architecture data, and its sources, reasoning and confidence ratings are credible.* It does not mean every rating is high — the limitations in §4 are part of what is approved.', '',
         '**Who should review.** An architect independent of the author, familiar with at least one of BIAN, ArchiMate or TOGAF. They need no employer data: everything here is public or synthetic. Expected effort: about a day for §5, longer if they re-check sources.', '',
         '## 2. What is being baselined', '',
         '| Part | Records | Count | Rendered as |', '|---|---|---|---|',
         f"| Entity types | `metamodel/a1…a4-*.json` | {len(ents)} ({sum(1 for e in ents if not e.get('abstract') and not e.get('artefact'))} instance types, {sum(1 for e in ents if e.get('artefact'))} artefacts, {sum(1 for e in ents if e.get('abstract'))} abstract) | `docs/architecture-entity-design.md` |",
         f"| Within-level relationships | `metamodel/level-relationships.json` | {len(rows)} rows + {len(lr['inheritance'])} inheritance | `docs/relationships-planning.md` |",
         f"| Cross-level relationship types | `schema/relationship-types.json` | {len(types)} | `docs/relationship-registry-spec.md` |",
         f"| Relationship rules | `metamodel/relationship-rules.json` | {len(rules)} | `docs/relationship-rules-spec.md` |",
         f"| Attributes | `metamodel/entity-attributes.json` | {len(at['core_fields'])} core, {len(common)} common, {len(attrs)} entity-specific, {len(derived)} derived ({len(dep)} deprecated kept for compatibility) | `docs/architecture-attribute-design.md` |",
         '| Logical data model | `sdem/logical.py`, `sdem/conformance.py` | 14 rules, all enforced | `docs/logical-data-model.md` |',
         f"| Physical data model | `schema/entities/*/*.schema.json` | {nschema} JSON Schemas | `docs/physical-data-model.md` |",
         '| Data-model review records | `metamodel/drafts/a1…a4-descriptive-attributes.json` | 4 (all approved) | `docs/drafts/data-model-a1…a4-draft.md` |', '',
         'Not in scope: the inference engine (not built), the Relationship Registry contents (institution data), and the example estates (synthetic test data).', '',
         '## 3. Evidence', '',
         '| Check | Result |', '|---|---|',
         f"| Unit tests | {ntests} tests — {tline} |",
         f"| Example estates against the enforced data model (`sdem-graph check`) | {est} estates, {inst} instances: **{err} errors**, {warn} warnings, all minimum-cardinality completeness gaps (an example, or the generated reference-structure estate, holds part of BIAN's structure) |",
         f"| Example instances against the physical schemas | {inst} instances, **{schema_bad} failing** |",
         f"| Within-level rows checked against a standard | {ver['verified']} against BIAN public material, {ver['verified_against_archi']} against the Archi oracle (open-source ArchiMate relationship tables); {ver['unverified_togaf']} TOGAF-only, {ver['sdem_reading']} SDEM reading |",
         '| Cross-level rules | all 69 plan rows covered by the use-case runs: 45 validated, 5 validated with findings, 19 not applicable (`docs/relationships-testing.md`, `docs/use-case-testing.md`) |',
         '| Source references | every entity, row, type, rule and attribute names its source; enforced by test |',
         '| Confidence | one rule (`sdem/confidence.py`) assigns every rating; CI fails if any record disagrees |',
         '| Generated documents | every document and schema is generated from the records; CI fails if any is stale |', '',
         f"**Confidence across {N} rated definitions** (entities, within-level rows, relationship types, core, common and entity-specific attributes): **{H} high ({round(100*H/N)}%), {M} medium ({round(100*M/N)}%), {L} low ({round(100*L/N)}%)**. High = defined by a public standard and checked; medium = built on a standard concept, or a standard that could not be checked; low = SDEM-defined with no standard basis.", '',
         '| Layer | High | Medium | Low |', '|---|---|---|---|']
    for name, xs in (('Entity types', ents), ('Within-level rows', rows), ('Relationship types', types), ('Core fields', at['core_fields']), ('Common attributes', common),
                     ('A1 attributes', [a for a in attrs if a['entity'].startswith('A1')]), ('A2 attributes', [a for a in attrs if a['entity'].startswith('A2')]),
                     ('A3 attributes', [a for a in attrs if a['entity'].startswith('A3')]), ('A4 attributes', [a for a in attrs if a['entity'].startswith('A4')])):
        h, m, l = hml(xs); o.append(f'| {name} | {h} | {m} | {l} |')
    h, m, l = hml(rules, 'basis_confidence'); o.append(f'| Relationship rules (basis) | {h} | {m} | {l} |')
    o += ['', '## 4. Known limitations (approved as part of the baseline)', '',
          f"1. **Login-gated standards not checked.** TOGAF and the ArchiMate specification text need an Open Group login. Affected: {', '.join(f'`{g}`' for g in gated)}. ArchiMate relationships were checked against the open-source Archi implementation instead.",
          '2. **BIAN below A2.** BIAN publishes no capability-to-Service-Domain mapping and almost nothing below A2, so most cross-level rules are SDEM\'s design, validated by the use cases rather than by a standard.',
          '3. **BIAN portal Service Domain pages** returned "not found" during the A2 review; no attribute rests on them. The HTTP-method default (DV-A2-02) rests partly on BIAN\'s published API files, not yet checked (medium).',
          '4. **ISO 3166** could not be opened (iso.org 403); `country` is medium.',
          f"5. **{len(lows)} SDEM-defined (low) attributes** — kept deliberately because they answer frequent design questions no open standard covers: " + ', '.join(lows) + '.',
          *([f"6. **{len(low_rows)} within-level row(s) resting on an SDEM reading** with no standard relationship: " + ', '.join(f"`{c['id']}` ({c['source_type']} {c['kind']} {c['target_type']})" for c in low_rows) + '.'] if low_rows else []),
          f"{6 + bool(low_rows)}. **Licensed BIAN validation** has not been done (needs BIAN membership).",
          f"{7 + bool(low_rows)}. **No real data yet.** Everything has been exercised on synthetic estates only; the first adapter on real data may find gaps.", '',
          '## 5. Review checklist', '',
          'Answer each with **yes / no / comment**. A "no" on 1–6 blocks the baseline; others can be accepted as findings.', '',
          '| # | Question | Where to look |', '|---|---|---|',
          '| 1 | Are the entity types the right set for business, BIAN service domain, application and technology architecture — nothing essential missing, nothing redundant? | `architecture-entity-design.md` |',
          '| 2 | Do the within-level relationships reflect BIAN and ArchiMate as you understand them? Spot-check ten rows against the cited source. | `relationships-planning.md` |',
          '| 3 | Are the nine cross-level relationship types meaningful and distinct? | `relationship-registry-spec.md` |',
          '| 4 | Spot-check ten attributes rated **high**: does the cited section really define that attribute? | `architecture-attribute-design.md` |',
          '| 5 | Is any attribute rated higher than its source justifies? | same |',
          '| 6 | Is there any sign of proprietary content (BIAN or Open Group text reproduced, employer entities or IDs)? | all documents |',
          '| 7 | Are the low (SDEM-defined) attributes worth keeping? | §4 item 5 |',
          '| 8 | Are the required/optional choices sensible (almost everything optional)? | `physical-data-model.md` |',
          '| 9 | Are derived attributes (criticality, HTTP method default) the right choice over stored ones? | `architecture-attribute-design.md` §4 |',
          '| 10 | Do the 14 logical rules make sense as errors vs warnings? | `logical-data-model.md` |',
          '| 11 | Could an adapter author build an exporter from the physical schemas alone? | `schema/entities/` |',
          '| 12 | Are the limitations in §4 acceptable for a first baseline? | §4 |', '',
          '## 6. Sign-off', '',
          '| Role | Name | Decision (approve / approve with findings / reject) | Date |', '|---|---|---|---|',
          '| Model owner | Steven Taumoepeau | | |', '| Independent reviewer | | | |', '',
          'Findings: record each as a GitHub issue labelled `baseline-0.8` and list them here.', '',
          '## 7. On approval', '',
          f'1. Record the approval in `metamodel/baseline.json` (baseline name, commit, reviewer, date, accepted findings).',
          '2. Set `metamodel_version` to `0.8.0` in the four level files and the example exports.',
          '3. Remove what was kept only for compatibility: the deprecated `accesses` attribute definition and the `sdmm` package and commands (planned for v0.8.0).',
          f'4. Tag the commit `{BASELINE}` and publish release v0.8.0 (with your approval).',
          '5. From then on, model changes go through a change record and a new version.', '']
    OUT.parent.mkdir(parents=True, exist_ok=True); OUT.write_text('\n'.join(o) + '\n', encoding='utf-8'); print('wrote', OUT.relative_to(ROOT))


if __name__ == '__main__':
    main()
